import {importWorkspaceDocument} from './document-import.mjs';
import {reportSources,normalizeRevisionReport,extractRevisionReportHtml,matchRevisionReport,normalizeConfirmedRevisionReport} from './revision-report-model.mjs';

let sequence=0;
const sourceName=source=>reportSources[source].replace(/（[^）]*）$/u,'');
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fingerprint=doc=>JSON.stringify({title:doc?.title||'',paragraphs:doc?.paragraphs?.map(p=>({id:p.id,original:typeof p.original==='string'?p.original:p.text}))});
function stylesheet(document){const href=new URL('./revision-report.css',import.meta.url).href;if(!document.querySelector('link[data-revision-report-style]')){const link=document.createElement('link');link.rel='stylesheet';link.href=href;link.dataset.revisionReportStyle='';document.head.append(link);}}

/** Existing user reports are separate from manuscript text; this opens no AI job. */
export function openRevisionReport({doc,getDocument=()=>doc,modal,notify=()=>{},onConfirm,initialReport,importDocument=importWorkspaceDocument,isCurrent=()=>true}={}){
 if(typeof modal!=='function'||typeof onConfirm!=='function'||!Array.isArray(getDocument()?.paragraphs))throw Error('报告定位需要论文原文、预览窗口与确认保存操作。');
 const document=globalThis.document,win=document.defaultView,route=win.location.hash,originalFingerprint=fingerprint(getDocument()),id='revision-report-'+(++sequence);stylesheet(document);
 let existing=null;if(initialReport)try{existing=normalizeConfirmedRevisionReport(initialReport,getDocument());}catch{notify('已保存报告定位与当前原文不一致，请重新导入并核对。');}
 modal('导入已有报告',`<section class="revision-report" id="${id}" aria-label="用户报告定位"><p class="rr-intro">导入已有报告，定位需要修改的原文。请逐项核对后确认。</p><div class="rr-fields"><label>报告来源<select data-rr-source>${Object.entries(reportSources).map(([key,label])=>`<option value="${key}"${key===(existing?.source||'other')?' selected':''}>${escape(sourceName(key))}</option>`).join('')}</select><small>来源由你选择，仅用于记录和定位。未调用检测平台核验。</small></label><label>上传已有报告<input type="file" data-rr-file accept=".txt,.docx,.pdf,.html,.htm"></label></div><p class="rr-boundary">支持 TXT、DOCX、PDF、HTML；TXT/DOCX 最大50MB，PDF最大20MB。</p><p data-rr-file-status role="status"></p><label class="rr-text-label">粘贴报告文本<textarea data-rr-text maxlength="100000" rows="7" placeholder="粘贴报告内容，也可上传报告文件。">${escape(existing?.evidence.map(part=>'原文片段：'+(part.reportExcerpt||part.excerpt)).join('\n\n')||'')}</textarea></label>${existing?'<p class="rr-saved-note">已恢复上次确认的摘录。重新勾选后可更新定位。</p>':''}<div class="rr-actions"><button type="button" class="btn secondary" data-rr-preview>预览并定位</button><span data-rr-status role="status">当前没有已确认的新定位。</span></div><p data-rr-error role="alert"></p><section data-rr-results hidden><h3>本次报告文本预览</h3><p data-rr-source-label></p><pre data-rr-report-preview></pre><h3>可核对的原文位置</h3><div data-rr-warnings></div><div data-rr-matches></div></section><footer class="rr-footer"><p>仅保存已确认的定位，不会覆盖论文正文。确认后仍需选择方案和费用。</p><button type="button" class="btn primary" data-rr-confirm disabled>确认所选位置</button></footer><details class="rr-help"><summary>使用说明</summary><p>PDF需确认后解析；暂不自动识别报告颜色，请核对匹配位置。</p><p>报告文字最多100,000字符，确认的定位记录最多10,000字符。内容较多时请分段导入。</p><p>粘贴片段可用“原文片段：”开头。仅标题或检测分数无法定位正文。</p><p>HTML仅提取文字与显式标记，不执行脚本或加载报告中的资源。只保存已确认摘录与段落位置，报告全文不会用于AI修改。PDF解析任务可在任务中心查看。</p></details></section>`);
 const host=document.getElementById(id);if(!host)throw Error('报告预览窗口未能打开。');const $=selector=>host.querySelector(selector),dialog=host.closest('dialog'),opened=dialog?.open,selected=new Set();
 let live=true,generation=0,loading=false,committing=false,parseController=null,candidates=[],report=null,htmlExcerpts=[],reportFileName=existing?.fileName||'',reportFormat='paste',observer=null;
 const current=()=>live&&host.isConnected&&(!opened||dialog.open)&&win.location.hash===route&&isCurrent();
 const sameDocument=()=>fingerprint(getDocument())===originalFingerprint;
 const message=(text,error=false)=>{if(current())$(error?'[data-rr-error]':'[data-rr-status]').textContent=text;};
 function controls(){if(!current())return;$('[data-rr-confirm]').disabled=loading||committing||!selected.size;for(const node of host.querySelectorAll('[data-rr-source],[data-rr-file],[data-rr-text],[data-rr-preview],[data-rr-pick]'))node.disabled=committing;$( '[data-rr-preview]').disabled=committing||loading;}
 function invalidate(){if(!current()||committing)return;generation++;parseController?.abort();loading=false;report=null;candidates=[];selected.clear();$('[data-rr-results]').hidden=true;message('报告或来源已变化，请重新预览并核对。');message('',true);controls();}
 function renderMatches(result){
  $('[data-rr-source-label]').textContent=sourceName(report.source)+(report.fileName?' · '+report.fileName:' · 粘贴文本');$('[data-rr-report-preview]').textContent=report.text;
  $('[data-rr-warnings]').innerHTML=result.warnings.map(warning=>'<p class="rr-warning">'+escape(warning)+'</p>').join('');
  $('[data-rr-matches]').innerHTML=result.candidates.map(candidate=>`<label class="rr-match${candidate.ambiguous?' rr-ambiguous':''}"><input type="checkbox" data-rr-pick="${candidate.id}"><span><b>第 ${candidate.paragraphIndex+1} 段${candidate.ambiguous?' · 有多个相同位置，请人工选择':''}</b>${candidate.excerptTruncated?'<small>以下为匹配内容的前部摘录</small>':''}<span class="rr-excerpt-label">论文原文摘录</span><pre>${escape(candidate.excerpt)}</pre><span class="rr-excerpt-label">已有报告中的实际摘录</span><pre>${escape(candidate.reportExcerpt)}</pre><details class="rr-help"><summary>查看定位详情</summary><p>原文字符 ${candidate.start}～${candidate.end} · 报告字符 ${candidate.reportStart}～${candidate.reportEnd}</p></details></span></label>`).join('');
  $('[data-rr-results]').hidden=false;message(result.candidates.length?`找到 ${result.candidates.length} 个可核对位置，尚未确认；请逐项勾选。`:'未定位到可核对原文，本次没有确认任何段落。');controls();
 }
 $('[data-rr-text]').addEventListener('input',()=>{htmlExcerpts=[];reportFormat='paste';reportFileName='';invalidate();});$('[data-rr-source]').addEventListener('change',invalidate);
 $('[data-rr-preview]').onclick=()=>{if(!current()||loading||committing)return;selected.clear();try{if(!sameDocument())throw Error('论文原文已变化，请关闭窗口后重新定位。');report=normalizeRevisionReport({source:$('[data-rr-source]').value,text:$('[data-rr-text]').value,fileName:reportFileName,format:reportFormat,explicitExcerpts:htmlExcerpts});const result=matchRevisionReport(getDocument(),report);candidates=result.candidates;message('',true);renderMatches(result);}catch(error){report=null;candidates=[];$('[data-rr-results]').hidden=true;message(error.message||'未能读取报告，请检查文本。',true);controls();}};
 $('[data-rr-matches]').addEventListener('change',event=>{const box=event.target.closest('[data-rr-pick]');if(!current()||!box||committing)return;box.checked?selected.add(box.dataset.rrPick):selected.delete(box.dataset.rrPick);message(`已勾选 ${selected.size} 个位置；确认后才会保存。`);controls();});
 $('[data-rr-file]').onchange=async event=>{
  const file=event.target.files?.[0];if(!file||!current()||committing)return;invalidate();const request=generation,extension=file.name.split('.').at(-1).toLowerCase(),status=$('[data-rr-file-status]'),abort=new win.AbortController();parseController=abort;
  const owns=()=>current()&&generation===request&&!abort.signal.aborted,typedBefore=$('[data-rr-text]').value;
  if(!['txt','docx','pdf','html','htm'].includes(extension)){status.textContent='请选择 TXT / DOCX / PDF / HTML 报告。';return;}if(file.size>(extension==='pdf'?20:50)*1024*1024){status.textContent=extension==='pdf'?'PDF 报告最大 20MB。':'本地报告文件最大 50MB。';return;}
  loading=true;controls();status.textContent='正在提取已有报告，与论文原文分别处理…';
  function adopt(extracted){if(!owns())return;const normalized=normalizeRevisionReport({source:$('[data-rr-source]').value,text:extracted.text,fileName:file.name,format:['html','htm'].includes(extension)?'html':extension,explicitExcerpts:extracted.explicitExcerpts||[]});$('[data-rr-text]').value=extracted.text;htmlExcerpts=extracted.explicitExcerpts||[];reportFileName=normalized.fileName;reportFormat=normalized.format;status.textContent=`已提取 ${normalized.text.length.toLocaleString('zh-CN')} 字符报告；尚未确认任何位置。`;if(extracted.warnings?.length){const details=document.createElement('details'),summary=document.createElement('summary');details.className='rr-help';summary.textContent='导入提示';details.append(summary);for(const warning of extracted.warnings){const paragraph=document.createElement('p');paragraph.textContent=String(warning);details.append(paragraph);}status.append(details);}message('请点击“预览并定位”，再人工勾选。');}
  try{
   let extracted;if(['html','htm'].includes(extension)){const text=await file.text();if(!owns())return;extracted=extractRevisionReportHtml(text,win.DOMParser);}else extracted=await importDocument(file,status,{signal:abort.signal});
   if(!owns())return;normalizeRevisionReport({source:$('[data-rr-source]').value,text:extracted.text,fileName:file.name});
   if($('[data-rr-text]').value!==typedBefore){status.textContent='报告提取已完成，保留了你在提取期间输入的文本。';const button=document.createElement('button');button.type='button';button.className='btn secondary';button.textContent='采用提取的报告文本';button.onclick=()=>adopt(extracted);status.append(button);}else if(typedBefore.trim()){
    status.textContent='报告提取已完成，当前粘贴内容仍保留。';const button=document.createElement('button');button.type='button';button.className='btn secondary';button.textContent='采用提取的报告文本';button.onclick=()=>adopt(extracted);status.append(button);
   }else adopt(extracted);
  }catch(error){if(owns())status.textContent=error.message||'报告提取失败，请粘贴可核对文本。';}
  finally{if(owns()){loading=false;controls();}}
 };
 $('[data-rr-confirm]').onclick=async()=>{
  if(!current()||loading||committing||!report||!selected.size)return;try{if(!sameDocument())throw Error('论文原文已变化，请关闭窗口后重新核对报告。');const payload=normalizeConfirmedRevisionReport({source:report.source,fileName:report.fileName,evidence:candidates.filter(candidate=>selected.has(candidate.id)),confirmedAt:new Date().toISOString()},getDocument());committing=true;message('',true);controls();await onConfirm(payload);if(!current())return;notify(`已保存 ${payload.paragraphIds.length} 段的用户确认摘录，论文原文保持原样。`);dispose();dialog?.close();}catch(error){if(current()){message(error.message||'确认记录未能保存，当前勾选仍保留，请重试。',true);committing=false;controls();}}
 };
 function dispose(){if(!live)return;live=false;generation++;parseController?.abort();observer?.disconnect();win.removeEventListener('hashchange',dispose);dialog?.removeEventListener('close',dispose);}
 win.addEventListener('hashchange',dispose);dialog?.addEventListener('close',dispose);if(win.MutationObserver){observer=new win.MutationObserver(()=>{if(!host.isConnected||opened&&!dialog?.open)dispose();});observer.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['open']});}
 return{dispose};
}
